        return 'C'

    # Count outcomes
    cc = cd = dc = dd = 0
    for me, op in history:
        if me == 'C':
            if op == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op == 'C':
                dc += 1
            else:
                dd += 1

    opp_C = cc + dc
    my_C = cc + cd

    # Last few moves
    last_me, last_op = history[-1]

    # Detect persistent defector: very few opponent C's over enough rounds
    if n >= 8 and opp_C <= max(1, n // 8):
        # Punish hard, but occasionally test to see if they changed
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Detect persistent cooperator: opponent almost always C
    if n >= 8 and opp_C >= n - 1:
        # Mostly exploit, but keep them cooperative occasionally
        if n % 9 == 0:
            return 'C'
        return 'D'

    # Detect tit-for-tat-ish opponent: opponent tends to mirror our previous move
    if n >= 4:
        mirror_hits = 0
        mirror_total = 0
        for i in range(1, n):
            prev_me = history[i - 1][0]
            cur_op = history[i][1]
            mirror_total += 1
            if cur_op == prev_me:
                mirror_hits += 1
        if mirror_total > 0 and mirror_hits * 4 >= mirror_total * 3:
            # Mirror them back, but occasionally be nice after their C
            if last_op == 'C':
                return 'C'
            # If they defected, defect; small chance to forgive
            if rng.random() < 0.08:
                return 'C'
            return 'D'

    # Detect alternating or noisy patterns: be cooperative but not exploitable
    if n >= 6:
        # If opponent has been fairly cooperative, cooperate
        if opp_C * 3 >= n * 2:
            # If last was D, retaliate briefly
            if last_op == 'D':
                # Check if this is isolated
                recent_defections = 0
                for i in range(max(0, n - 4), n):
                    if history[i][1] == 'D':
                        recent_defections += 1
                if recent_defections >= 3:
                    return 'D'
                if rng.random() < 0.7:
                    return 'D'
                return 'C'
            return 'C'

    # If opponent has been mostly defecting, defect
    if n >= 4 and opp_C * 2 < n:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Default: start cooperative, respond to last defection with defection sometimes
    if last_op == 'D':
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Otherwise cooperate
    return 'C'

